public def DifferentialTargetCoset
    (E : SpectralSequence C ι) (r : ℤ) (k : ι) {T : C}
    (y : T ⟶ (E.ssData (k + E.diffDeg r)).V) :
    Set (T ⟶ (E.ssData (k + E.diffDeg r)).V) :=
