public def TargetCoset (f : FilteredMorphism F G) (k : ω) (s n : ℤ)
    {T : C} (y : T ⟶ G.associatedGraded (s + n) k) :
    Set (T ⟶ G.associatedGraded (s + n) k) :=
  {z | z - y ∈ TargetIndeterminacy f k s n T}

